'use client';

import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useState } from 'react';

interface Project {
    id: string;
    title: string;
    description: string;
    techStack: string;
    imageUrl?: string | null;
    githubUrl?: string | null;
    demoUrl?: string | null;
}

export default function ProjectCard({ project }: { project: Project }) {
    const router = useRouter();
    const [isDeleting, setIsDeleting] = useState(false);

    const handleDelete = async () => {
        if (!confirm('Are you sure you want to delete this project?')) return;

        setIsDeleting(true);
        try {
            const res = await fetch(`/api/projects/${project.id}`, {
                method: 'DELETE',
            });

            if (!res.ok) throw new Error('Failed to delete project');

            router.refresh();
        } catch (error) {
            console.error(error);
            alert('Failed to delete project');
        } finally {
            setIsDeleting(false);
        }
    };

    return (
        <div className="bg-white/5 border border-white/10 rounded-xl p-6 hover:border-blue-500/50 transition-all duration-300 group flex flex-col h-full">
            {project.imageUrl && (
                <div className="w-full h-48 mb-4 rounded-lg overflow-hidden">
                    <img
                        src={project.imageUrl}
                        alt={project.title}
                        className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                    />
                </div>
            )}
            <h3 className="text-xl font-bold text-white mb-2 group-hover:text-blue-400 transition-colors">
                {project.title}
            </h3>
            <p className="text-gray-400 mb-4 line-clamp-3 flex-grow">{project.description}</p>

            <div className="flex flex-wrap gap-2 mb-6">
                {project.techStack.split(',').map((tech) => (
                    <span
                        key={tech}
                        className="px-3 py-1 text-xs font-medium bg-blue-500/10 text-blue-400 rounded-full border border-blue-500/20"
                    >
                        {tech.trim()}
                    </span>
                ))}
            </div>

            <div className="flex gap-4 items-center mt-auto">
                {project.githubUrl && (
                    <a
                        href={project.githubUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-sm text-gray-400 hover:text-white transition-colors flex items-center gap-2"
                    >
                        GitHub
                    </a>
                )}
                {project.demoUrl && (
                    <a
                        href={project.demoUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-sm text-blue-400 hover:text-blue-300 transition-colors flex items-center gap-2"
                    >
                        Live Demo
                    </a>
                )}
                <div className="ml-auto flex gap-3">
                    <Link
                        href={`/admin/edit/${project.id}`}
                        className="text-sm text-yellow-500 hover:text-yellow-400 transition-colors"
                    >
                        Edit
                    </Link>
                    <button
                        onClick={handleDelete}
                        disabled={isDeleting}
                        className="text-sm text-red-500 hover:text-red-400 transition-colors disabled:opacity-50"
                    >
                        {isDeleting ? 'Deleting...' : 'Delete'}
                    </button>
                </div>
            </div>
        </div>
    );
}
